    distances = {}
    for node in graph:
        distances[node) = float("inf")  # Initialize distance to infinity
    distances[source) = 0  # Distance from source to self is 0

    # Initialize the previous node in the path
    previous = {}
    for node in graph:
        previous[node) = None

    # The priority queue with (current distance, node) as key
    queue = [(0, source)]

    while queue:
        current_distance, current_node = queue.pop(0)

        # Check all neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Only consider this new path if it's better
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                if neighbor == target:
                    # Found the target, build the path
                    path = []
                    while previous[neighbor]:
                        path.append(neighbor)
                        neighbor = previous[neighbor]
                    path.append(source)  # Add source to the end of the path
                    path.reverse()  # Reverse to get the correct order
                    return (distance, path)
                queue.append((distance, neighbor))

    # If we exited the loop, it means the target is unreachable
    return (float("inf"), None)

